import Vue, { defineComponent } from 'vue';
import gsap from 'gsap';

import { GameList, GameWindow, IGameInGameManager } from '@game-studio/game-in-game';
import { PromoDetails, TimeKeeperLimit } from '@game-studio/server-comms';
import { IBootstrapConfigLocale, IGlobalBootstrapConfig } from '@game-studio/shell-connection';

import { default as ActionMenu } from '../action-menu/action-menu.vue';
import { default as DebugInspectorView } from '../debug/pixi-editor/pixi-editor-view.vue';
import { default as DebugInspectorSelectionView } from '../debug/pixi-editor/selection-view.vue';
import { default as GameView } from '../game/game-view.vue';
import { default as PrizeLeague } from '../prize-league/prize-league.vue';
import { default as SettingsMenu } from '../settings-menu/settings-menu.vue';
import { default as WalletView } from '../wallet-manager/wallet-manager.vue';

import { BaseGame, container, Injects, OverlaysEventEmitter, queryStringParams } from '../..';
import { inversifyContainer } from '../../inversify/container';
import { useCompanionState } from '../../models/companion-state';
import { gameConfig } from '../../models/config-model';
import { demoState } from '../../models/demo-model';
import { OperatorModel } from '../../models/operator-model';
import { userModel } from '../../models/user';
import { userPreferences } from '../../models/user-preferences';
import { device } from '../../services/device';
import { environment } from '../../services/environment';
import { eventEmitter } from '../../services/event-emitter';

export default defineComponent({
    name: 'App',
    components: {
        GameView,
        WalletView,
        DebugInspectorView,
        DebugInspectorSelectionView,
        ActionMenu,
        GameList,
        GameWindow,
        PrizeLeague
    },
    computed: {
        deviceClass(): string {
            if (device.type.value === 'mobile') {
                return `${device.type.value} phone`;
            }
            return device.type.value;
        },
        subGameClass(): string {
            return queryStringParams.isSubGame ? 'sub-game' : '';
        },
        settingsComponent() {
            return SettingsMenu;
        },
        settingsLocale() {
            return inversifyContainer.strings.settings;
        },
        settingsApiUrl() {
            return inversifyContainer.endPoints.urls[environment].recentWinners + inversifyContainer.adminSettings.recentWinnersName;
        },
        chatRulesUrl() {
            const versions = inversifyContainer.translationVersions;
            if (versions) { // translation versions are only for the new cdn path so if provided we need to use the new path
                return `${inversifyContainer.endPoints.urls[environment].cdnTranslationsRoot}arcade-chat-rules/${versions.chatRules}/translations.json`;
            }
            return `${inversifyContainer.endPoints.urls[environment].cdnRoot}settings/${inversifyContainer.adminSettings.settingsStrings}/chat-rules.json`;
        },
        chatRulesOverride() {
            return inversifyContainer.chatRulesOverride;
        },
        isNotProductionEnv(): boolean {
            return environment !== 'live';
        },
        vuehtpComponent() {
            return inversifyContainer.vueHtpVue;
        },
        style() {
            const operatorTheme = inversifyContainer.get<OperatorModel>(Injects.OperatorModel).theme;
            return {
                '--themeFont': operatorTheme.fontName,
                '--themeDarkAccent': operatorTheme.darkAccent.string,
                '--themeMidAccent': operatorTheme.midAccent.string,
                '--themeLightAccent': operatorTheme.lightAccent.string,
                '--themeVeryLightAccent': operatorTheme.veryLightAccent.string
            };
        }
    },
    data() {
        const operatorTheme = inversifyContainer.get<OperatorModel>(Injects.OperatorModel).theme;
        return {
            device: device,
            country: queryStringParams.locale,
            isPrizeLeaguePanelSmall: false,
            chatConfig: {
                userListEnabled: gameConfig.coreFeatures.showChatUserList ?? false,
                platform: 'arcade',
                operatorId: queryStringParams.launchedFrom === 'arcade' ? 'tombola-arcade' : 'tombola',
                environment: environment,
                gameName: gameConfig.chatName,
                friendlyGameNameMap: BaseGame.gameNameMap,
                warmBackground: false,
                chatStyle: {
                    backgroundColor: inversifyContainer.skin.config.chatBgColour,
                    color: '#FFFFFF'
                },
                currencySettings: { ...inversifyContainer.currencySettings, roundOnWholeUnits: true },
                reconnectButtonStyle: { backgroundColour: operatorTheme.midAccent.string, textColour: '#FFFFFF' },
            } as IGlobalBootstrapConfig,
        };
    },
    setup() {
        const { isActionMenuEnabled, isChatEnabled, isChatFullScreen, isGameInGameEnabled, isPrizeLeagueEnabled, isPanelOpen, menuHeight, chatPanelHeight, isGameInGameOpen, isSubGameOpen, isChatOpen, isPrizeLeagueOpen, initialise } = useCompanionState();

        // shallowRef => this.chatTween is a typed instance property that only
        // reacts to whole-value replacement; the gsap Tween is never deep-observed.

        return {
            chatTween: undefined as gsap.core.Tween | undefined,
            companion: {
                isMenuEnabled: isActionMenuEnabled,
                isChatEnabled,
                isPrizeLeagueEnabled,
                isPrizeLeagueOpen,
                isGameInGameEnabled,
                isGameInGameOpen,
                isSubGameOpen,
                isChatOpen,
                isOpen: isPanelOpen,
                isChatFullScreen: isChatFullScreen,
                menuHeight,
                panelHeight: chatPanelHeight,
                initialise
            }
        };
    },
    mounted(): void {
        this.companion.initialise();

        device.visibility.on('visibilityChanged', this.onVisibilityChanged, this);
        // TODO: investigate why this is received twice each orientation, only the second one has correct values.
        device.orientation.on('onOrientationStateChanged', this.onOrientationchangeend, this);
        Vue.nextTick(this.sizeView, this);

        window.$formatCurrency = function (value: number): string {
            return inversifyContainer.currencyFormatter.precise(value);
        };

        this.chatConfig = {
            ...this.chatConfig,
            userId: userModel.userId,
            crosscheck: userModel.crossCheck,
            chatColour: userPreferences.chatColour,
            chatSize: userPreferences.chatSize,
            translations: inversifyContainer.strings.chat,
            locale: this.country as IBootstrapConfigLocale,
            isInDemoMode: demoState.isDemoMode,
        } as IGlobalBootstrapConfig;

        if (this.companion.isChatEnabled.value) {
            inversifyContainer.frameConnection.createChat(
                this.$refs['chat-iframe'] as HTMLIFrameElement,
                inversifyContainer.endPoints.urls[environment].chat!
            );

            // Setup is async and waits for onInit internally
            inversifyContainer.frameConnection.chat.setup(this.chatConfig).then(() => {
                // Chat is now fully initialized, safe to set demo mode
                if (demoState.isUnauthenticatedDemo) {
                    demoState.notifyChatDemoMode();
                }
            });
        }

        const gigManager = inversifyContainer.get<IGameInGameManager>(Injects.GameInGameManager);
        gigManager.setIFrame(this.$refs['game-in-game-iframe'] as HTMLIFrameElement);

        eventEmitter.on('GLOBAL_LOW_BALANCE', this.onLowBalanceError, this);
        eventEmitter.on('GLOBAL_ACCOUNT_LOCKED', this.onAccountLockedError, this);
        eventEmitter.on('GLOBAL_STAKE_ALERT', this.onStakeAlertError, this);
        eventEmitter.on('CHAT_TOGGLE_FULL_SCREEN', this.chatToggleFullScreen, this);
        inversifyContainer.gameServer.on('ON_TIMEKEEPER_RESULT', this.onTimeKeeperResult, this);
        inversifyContainer.gameServer.on('ON_REALITYCHECK_RESULT', this.onRealityCheckResult, this);
        inversifyContainer.gameServer.on('ON_LOWBALANCE_ERROR', this.onLowBalanceError, this);
        inversifyContainer.gameServer.on('ON_PROMO_RESULT', this.onPromoResult, this);
        inversifyContainer.gameServer.on('ON_COOLOFF_WINDOW_HIT', this.onCooloffWindowError, this);
        inversifyContainer.gameServer.on('ON_TIME_LIMIT_REACHED_WINDOW_HIT', this.onTimeLimitReachedWindowError, this);
        inversifyContainer.gameServer.on('ON_GAME_IN_GAME_FREEZE', this.onGameInGameFreeze, this);
        inversifyContainer.gameServer.on('ON_ARCADE_SELF_EXCLUSION', this.onSelfExclusion, this);
        inversifyContainer.gameServer.on('ON_BINGO_SELF_EXCLUSION', this.onSelfExclusion, this);

        // Add keyboard shortcut for debug inspector (Cmd+Shift+L)
        if (environment !== 'live') {
            window.addEventListener('keydown', this.onKeyDown);
        }
    },
    methods: {
        onLoadComplete(): void {
            this.$emit('loadComplete');
        },
        onKeyDown(event: KeyboardEvent): void {
            // Check for Cmd+Shift+L (Mac) or Ctrl+Shift+L (Windows/Linux)
            if ((event.metaKey || event.ctrlKey) && event.shiftKey && event.key === 'l') {
                event.preventDefault();
                eventEmitter.emit('DEBUG_INSPECTOR_SHOW_REQUESTED', true);
            } else if ((event.metaKey || event.ctrlKey) && event.shiftKey && event.key === 'd') {
                event.preventDefault();
                eventEmitter.emit('POPUP_TOGGLE_DEBUG_OVERLAY');
            }
        },
        onOrientationchangeend(): void {
            // clears the width before recalculating so device.viewport.width reports correctly on Android Apps
            const gameViewEl = (this.$refs.gameView as InstanceType<typeof GameView>).$el as HTMLElement;
            gameViewEl.style.width = '';

            this.companion.isChatFullScreen.value = false;

            (this.$refs.actionMenu as any)?.onOrientationChange();
            // Next tick to ensure DOM is updated before we attempt to size elements based on it
            Vue.nextTick(() => {
                this.sizeView();
                eventEmitter.emit('GLOBAL_ORIENTATION_CHANGE');
            });
        },
        sizeView(): void {
            const gameViewEl = (this.$refs.gameView as InstanceType<typeof GameView>).$el as HTMLElement;
            if (queryStringParams.isSubGame) {
                gameViewEl.style.position = 'absolute';
                gameViewEl.style.top = `calc(50% - ${device.gameHeight * 0.5}px)`;
            } else {
                this.updateChatHeight();
                this.updateGameInGameHeight();
                this.updatePrizeLeagueHeight();
            }

            const targetHeight = queryStringParams.isSubGame ? device.gameHeight : device.availableHeight;
            gameViewEl.style.height = `${targetHeight}px`;
            gameViewEl.style.width = `${device.gameWidth}px`;

            if (device.type.isIosNative) {
                // iOS app is misbehaving with height when the keyboard is opened
                // setting the appView height to the inner height keeps it the full height as we expect
                (this.$refs.appView as HTMLElement).style.height = `${window.innerHeight}px`;
            }
        },
        onVisibilityChanged(isVisible: boolean): void {
            if (!isVisible) {
                eventEmitter.emit('GLOBAL_SUSPEND');
            }
        },
        //#region Error Handling Methods
        onLowBalanceError(): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'low-balance', data: { balance: userModel.totalBalance.startBalance } });
        },
        onAccountLockedError(): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'id-verification' });
        },
        onStakeAlertError(resultCode: number): void {
            // TODO: add some error checking if these strings don't exist?
            // ---- Currently stakeAlert only exists in strings for a region that use it (see spain)
            const strings = container.strings.overlays.stakeAlert!;
            const title = strings.title;
            const message = strings.resultCodeMessages?.[resultCode] ?? strings.message;
            const btnLabel = strings.close;

            OverlaysEventEmitter.emit('showPopup', title, message, btnLabel);
        },
        //#endregion
        //#region Game Server Methods
        onCooloffWindowError(): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'cooloff-window' });
        },
        onTimeLimitReachedWindowError(): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'time-limit-reached' });
        },
        onTimeKeeperResult(data: TimeKeeperLimit): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'time-keeper', data: { limit: data.Value } });
        },
        onRealityCheckResult(): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'reality-check' });
        },
        onPromoResult(promoDetails: PromoDetails[]): void {
            promoDetails.forEach((promo) => {
                Object.assign(promo, { isPromo: true });
                eventEmitter.emit('GLOBAL_PROMO', promo);
            });
        },
        onGameInGameFreeze(): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'game-in-game-freeze' });
        },
        onSelfExclusion(data: any): void {
            container.frameConnection.operator.onUserActionRequired({ type: 'self-exclusion', data });
        },
        onFreePlayMessage(callback: (data: number) => void, context: Vue): void {
            eventEmitter.on('GLOBAL_FREE_PLAY_EARNED', callback, context);
        },
        onFreePlayEnded(callback: (payout: number, message: string) => void, context: Vue): void {
            eventEmitter.on('GLOBAL_FREE_PLAY_ENDED', callback, context);
        },
        onCloseEndFreePlay(): void {
            inversifyContainer.cabinet.leaveFreePlay();
        },
        //#endregion
        //#region Companion Methods
        chatToggleFullScreen(): void {
            this.companion.isChatFullScreen.value = !this.companion.isChatFullScreen.value;
            this.updateChatHeight();
        },
        updateChatHeight(options?: { tweenDuration: number }): void {
            if (!this.companion.isChatEnabled.value) { return; }
            if (useCompanionState().mode.value === 'side') { return; }

            const currentChatHeight = this.companion.isChatFullScreen.value ? device.viewport.height - this.companion.menuHeight.value : this.companion.panelHeight.value;
            const duration = options?.tweenDuration ?? 0;
            this.tweenChatHeight(currentChatHeight, duration);
        },
        tweenChatHeight(height: number, duration: number = 0.25): void {
            this.chatTween?.kill();
            this.chatTween = gsap.to((this.$refs['chat-iframe'] as HTMLIFrameElement), {
                duration: duration,
                height: `${height}px`
            });
        },
        updateGameInGameHeight(): void {
            if (!this.companion.isGameInGameEnabled.value) { return; }
            const companionState = useCompanionState();
            if (companionState.mode.value === 'side') { return; }

            const gameInGamePanel = this.$refs['game-in-game-panel'] as HTMLDivElement;
            const gigHeight = this.companion.panelHeight.value;
            gameInGamePanel.style.height = `${gigHeight}px`;
            companionState.gigPanelHeight.value = gigHeight;
            // TODO: May introduce a more dynamic height for gig in the future so it doesn't take up most of the screen on mobile portrait. Based on Product requirements.
        },
        updatePrizeLeagueHeight(): void {
            if (!this.companion.isPrizeLeagueEnabled.value) { return; }
            const companionState = useCompanionState();
            if (companionState.mode.value === 'side') { return; }

            const prizeLeaguePanel = (this.$refs['prize-league-panel'] as InstanceType<typeof PrizeLeague>).$el as HTMLDivElement;
            const prizeLeagueHeight = this.companion.panelHeight.value;
            prizeLeaguePanel.style.height = `${prizeLeagueHeight}px`;
            companionState.prizeLeaguePanelHeight.value = prizeLeagueHeight;
            this.isPrizeLeaguePanelSmall = (device.gameWidth / prizeLeagueHeight > 1.45) && device.type.isMobile;
        }
        //#endregion
    }
});
